style.css:
@-moz-document domain("google.com") {
/* Background */
  body {
    background: linear-gradient(135deg, #1a0000, #4a0000);
    color: #f0f0f0;
    font-family: 'Playfair Display', serif; /* Elegant font */
    transition: all 0.3s ease-in-out;
  }

  /* Logo */
  #hplogo {
    filter: drop-shadow(0 0 15px #d72638) brightness(0.8);
  }

  /* Search Box */
  input[type="text"] {
    background: #330000;
    border: 1px solid #770000;
    color: #f8f8f8;
    padding: 10px;
    font-size: 1.2rem;
    border-radius: 5px;
    box-shadow: 0 0 10px #770000;
    transition: all 0.3s ease-in-out;
  }

  input[type="text"]:focus {
    border-color: #d72638;
    box-shadow: 0 0 15px #d72638;
    outline: none;
  }

  /* Search Button */
  input[type="submit"], button {
    background: #4a0000;
    color: #f8f8f8;
    border: 1px solid #770000;
    padding: 8px 16px;
    font-size: 1rem;
    font-family: 'Playfair Display', serif;
    border-radius: 5px;
    cursor: pointer;
    transition: all 0.3s ease-in-out;
  }

  input[type="submit"]:hover, button:hover {
    background: #770000;
    border-color: #d72638;
    box-shadow: 0 0 15px #d72638;
  }

  /* Links */
  a {
    color: #d72638;
    text-decoration: none;
    transition: all 0.3s ease-in-out;
  }

  a:hover {
    color: #ff5f5f;
    text-decoration: underline;
  }

  /* Footer */
  #fbar, #footcnt {
    background: #1a0000;
    color: #f0f0f0;
    font-size: 0.9rem;
  }

  #fbar a, #footcnt a {
    color: #770000;
  }

  #fbar a:hover, #footcnt a:hover {
    color: #d72638;
  }

  /* Miscellaneous */
  .gb_g, .gb_h {
    color: #f8f8f8 !important;
  }
}
